{"implementation":"def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    members = {}
    for node, group in refinement.items():
        members.setdefault(group, []).append(node)
    for group in members:
        members[group].sort()
    edge_weights = {}
    for u, v, w in edges:
        cu = refinement[u]
        cv = refinement[v]
        if cu <= cv:
            key = (cu, cv)
        else:
            key = (cv, cu)
        edge_weights[key] = edge_weights.get(key, 0) + w
    aggregate_edges = sorted([[k[0], k[1], v] for k, v in edge_weights.items()], key=lambda x: (x[0], x[1]))
    return {'aggregate_edges': aggregate_edges, 'members': members}
"}
